// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn job_info_default_construction() {
        let info = JobInfo {
            job_id: 42,
            document_name: "test.docx".to_string(),
            user_name: "jsmith".to_string(),
            status: 0,
            datatype: "XPS_PASS".to_string(),
            pages: 3,
        };
        assert_eq!(info.job_id, 42);
        assert_eq!(info.document_name, "test.docx");
        assert_eq!(info.user_name, "jsmith");
        assert_eq!(info.status, 0);
        assert_eq!(info.datatype, "XPS_PASS");
        assert_eq!(info.pages, 3);
    }

    #[test]
    fn job_info_clone_equality() {
        let info = JobInfo {
            job_id: 1,
            document_name: "a".to_string(),
            user_name: "b".to_string(),
            status: 0,
            datatype: "RAW".to_string(),
            pages: 0,
        };
        let cloned = info.clone();
        assert_eq!(info, cloned);
    }

    #[test]
    fn is_job_printing_with_zero_status() {
        assert!(!is_job_printing(0));
    }

    #[test]
    fn is_job_printing_with_printing_bit() {
        assert!(is_job_printing(JOB_STATUS_PRINTING));
    }

    #[test]
    fn is_job_printing_with_mixed_bits() {
        assert!(is_job_printing(JOB_STATUS_PRINTING | 0x04));
        assert!(!is_job_printing(0x04));
    }

    #[test]
    fn pwstr_to_string_null() {
        let s = pwstr_to_string(windows::core::PWSTR::null());
        assert_eq!(s, "");
    }
}

//! XPS text extraction parser (M017 T03).
//!
//! Extracts text content from XPS spool files (ZIP archives containing
//! FixedDocumentSequence + FixedDocument + page `.fpage` XML files).
//!
//! ## Redaction
//!
//! Text content is parsed in-memory and never written to disk or logs.
//! Only document metadata (name, job ID) appears in audit events.

use std::io::{Cursor, Read};

use anyhow::{Context, Result};
use quick_xml::events::Event;
use quick_xml::Reader;

/// Extracts plain text from XPS spool bytes.
///
/// # Arguments
///
/// * `xps_bytes` — Raw bytes of the XPS file (a ZIP archive).
/// * `max_pages` — Maximum number of `.fpage` files to parse. 0 means
///   return empty string immediately.
///
/// # Returns
///
/// * `Ok(text)` — Concatenated text from all parsed pages, space-separated.
///   Empty string if no text is found or `max_pages` is 0.
/// * `Err(...)` — Malformed ZIP or other unrecoverable read error.
///
/// # Failure modes
///
/// * Malformed ZIP → error returned (no panic).
/// * Missing `.fpage` entries → empty string (caller falls back to metadata-only).
/// * XML parse error on one page → that page is skipped, others continue.
pub fn extract_text(xps_bytes: &[u8], max_pages: usize) -> Result<String> {
    if max_pages == 0 || xps_bytes.is_empty() {
        return Ok(String::new());
    }

    let cursor = Cursor::new(xps_bytes);
    let mut archive = zip::read::ZipArchive::new(cursor)
        .context("invalid XPS/ZIP archive")?;

    let mut page_count: usize = 0;
    let mut all_text: Vec<String> = Vec::new();

    // Collect matching entry indices first to avoid borrow issues with archive.
    let mut page_indices: Vec<usize> = Vec::new();
    for i in 0..archive.len() {
        let file = archive.by_index(i)?;
        let name_lower = file.name().to_lowercase();
        if name_lower.contains("/pages/") && name_lower.ends_with(".fpage") {
            page_indices.push(i);
        }
    }

    for idx in page_indices {
        if page_count >= max_pages {
            break;
        }

        let mut file = archive.by_index(idx)?;
        let mut xml_bytes = Vec::new();
        if let Err(e) = file.read_to_end(&mut xml_bytes) {
            // Skip unreadable pages.
            tracing::warn!(page = %file.name(), error = %e, "failed to read XPS page");
            continue;
        }

        match parse_page_text(&xml_bytes) {
            Ok(page_text) => {
                if !page_text.is_empty() {
                    all_text.push(page_text);
                }
            }
            Err(e) => {
                tracing::warn!(page = %file.name(), error = %e, "failed to parse XPS page XML");
                // Skip corrupted pages, continue with others.
            }
        }

        page_count += 1;
    }

    Ok(all_text.join(" "))
}

/// Parse a single `.fpage` XML buffer and extract text from `Glyphs` elements.
fn parse_page_text(xml: &[u8]) -> Result<String> {
    let mut reader = Reader::from_reader(xml);
    reader.config_mut().trim_text(true);

    let mut buf = Vec::new();
    let mut page_text: Vec<String> = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) | Ok(Event::Start(ref e)) => {
                if e.name().as_ref() == b"Glyphs" {
                    for attr_result in e.attributes() {
                        let attr = attr_result.context("invalid XML attribute")?;
                        if attr.key.as_ref() == b"UnicodeString" {
                            let value = attr
                                .decode_and_unescape_value(reader.decoder())
                                .unwrap_or_default()
                                .into_owned();
                            if !value.is_empty() {
                                page_text.push(value);
                            }
                        }
                    }
                }
            }
            Ok(Event::Eof) => break,
            Err(e) => {
                anyhow::bail!("XML parse error at position {}: {:?}", reader.buffer_position(), e);
            }
            _ => {}
        }
        buf.clear();
    }

    Ok(page_text.join(" "))
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    /// Build a minimal in-memory XPS (ZIP) fixture with known text.
    fn build_xps_fixture() -> Vec<u8> {
        let mut buf = Cursor::new(Vec::new());
        {
            let mut zip = zip::write::ZipWriter::new(&mut buf);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);

            // Required XPS structure files.
            let content_types = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>
  <Default Extension="fpage" ContentType="application/vnd.ms-package.xps-fixedpage+xml"/>
</Types>"#;
            zip.start_file("[Content_Types].xml", options).unwrap();
            zip.write_all(content_types.as_bytes()).unwrap();

            let fdseq = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<FixedDocumentSequence xmlns="http://schemas.microsoft.com/xps/2005/06">
  <DocumentReference Source="Documents/1/FixedDocument.fdoc"/>
</FixedDocumentSequence>"#;
            zip.start_file("FixedDocumentSequence.fdseq", options).unwrap();
            zip.write_all(fdseq.as_bytes()).unwrap();

            let fdoc = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<FixedDocument xmlns="http://schemas.microsoft.com/xps/2005/06">
  <PageContent Source="Pages/1.fpage"/>
  <PageContent Source="Pages/2.fpage"/>
</FixedDocument>"#;
            zip.start_file("Documents/1/FixedDocument.fdoc", options).unwrap();
            zip.write_all(fdoc.as_bytes()).unwrap();

            let page1 = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<FixedPage xmlns="http://schemas.microsoft.com/xps/2005/06" Width="816" Height="1056">
  <Glyphs UnicodeString="Hello XPS World" FontRenderingEmSize="12"/>
  <Glyphs UnicodeString="Second sentence" FontRenderingEmSize="12"/>
</FixedPage>"#;
            zip.start_file("Documents/1/Pages/1.fpage", options).unwrap();
            zip.write_all(page1.as_bytes()).unwrap();

            let page2 = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<FixedPage xmlns="http://schemas.microsoft.com/xps/2005/06" Width="816" Height="1056">
  <Glyphs UnicodeString="Page two text" FontRenderingEmSize="12"/>
</FixedPage>"#;
            zip.start_file("Documents/1/Pages/2.fpage", options).unwrap();
            zip.write_all(page2.as_bytes()).unwrap();

            zip.finish().unwrap();
        }
        buf.into_inner()
    }

    #[test]
    fn extract_text_returns_known_text() {
        let xps = build_xps_fixture();
        let text = extract_text(&xps, 10).unwrap();
        assert!(text.contains("Hello XPS World"));
        assert!(text.contains("Second sentence"));
        assert!(text.contains("Page two text"));
    }

    #[test]
    fn extract_text_max_pages_zero() {
        let xps = build_xps_fixture();
        let text = extract_text(&xps, 0).unwrap();
        assert_eq!(text, "");
    }

    #[test]
    fn extract_text_max_pages_one() {
        let xps = build_xps_fixture();
        let text = extract_text(&xps, 1).unwrap();
        assert!(text.contains("Hello XPS World"));
        assert!(!text.contains("Page two text"));
    }

    #[test]
    fn extract_text_empty_zip_bytes() {
        let result = extract_text(b"not a zip", 10);
        assert!(result.is_err());
    }

    #[test]
    fn extract_text_no_fpage_entries() {
        let mut buf = Cursor::new(Vec::new());
        {
            let mut zip = zip::write::ZipWriter::new(&mut buf);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);
            zip.start_file("readme.txt", options).unwrap();
            zip.write_all(b"no pages here").unwrap();
            zip.finish().unwrap();
        }
        let text = extract_text(&buf.into_inner(), 10).unwrap();
        assert_eq!(text, "");
    }

    #[test]
    fn extract_text_corrupted_xml_page() {
        let mut buf = Cursor::new(Vec::new());
        {
            let mut zip = zip::write::ZipWriter::new(&mut buf);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);

            // Page 1: valid XML with text.
            let page1 = r#"<?xml version="1.0"?>
<FixedPage xmlns="http://schemas.microsoft.com/xps/2005/06">
  <Glyphs UnicodeString="Valid text" FontRenderingEmSize="12"/>
</FixedPage>"#;
            zip.start_file("Documents/1/Pages/1.fpage", options).unwrap();
            zip.write_all(page1.as_bytes()).unwrap();

            // Page 2: corrupted XML (unclosed tag).
            let page2 = r#"<?xml version="1.0"?>
<FixedPage xmlns="http://schemas.microsoft.com/xps/2005/06">
  <Glyphs UnicodeString="Broken" FontRenderingEmSize="12">
</FixedPage>"#;
            zip.start_file("Documents/1/Pages/2.fpage", options).unwrap();
            zip.write_all(page2.as_bytes()).unwrap();

            zip.finish().unwrap();
        }
        let text = extract_text(&buf.into_inner(), 10).unwrap();
        assert!(text.contains("Valid text"));
        // Page 2 should be skipped due to XML error, so "Broken" won't appear.
        assert!(!text.contains("Broken"));
    }

    #[test]
    fn extract_text_empty_bytes() {
        let text = extract_text(b"", 10).unwrap();
        assert_eq!(text, "");
    }

    #[test]
    fn extract_text_case_insensitive_fpage() {
        let mut buf = Cursor::new(Vec::new());
        {
            let mut zip = zip::write::ZipWriter::new(&mut buf);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);

            let page = r#"<?xml version="1.0"?>
<FixedPage xmlns="http://schemas.microsoft.com/xps/2005/06">
  <Glyphs UnicodeString="Case insensitive" FontRenderingEmSize="12"/>
</FixedPage>"#;
            // Uppercase path — still matches case-insensitive search.
            zip.start_file("DOCUMENTS/1/PAGES/1.FPAGE", options).unwrap();
            zip.write_all(page.as_bytes()).unwrap();

            zip.finish().unwrap();
        }
        let text = extract_text(&buf.into_inner(), 10).unwrap();
        assert!(text.contains("Case insensitive"));
    }
}

//! Offline mode (T-18, F-AGT-11).
//!
//! Detects when the Policy Engine is unreachable and falls back to the local
//! [`Cache`](crate::cache::Cache).  When the engine comes back online,
//! reconnects automatically via a heartbeat loop.
//!
//! ## Fail-closed semantics
//!
//! - T3/T4 resources: DENY on cache miss (fail-closed).
//! - T1/T2 resources: ALLOW on cache miss (default-allow for non-sensitive).
//!
//! The caller should consult [`offline_decision`] when `EngineClient::evaluate`
//! fails with `EngineClientError::Unreachable`.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use dlp_common::{AgentInfo, Classification, EvaluateRequest, EvaluateResponse};
use tracing::{debug, info, warn};

use crate::cache::{self, Cache};
use crate::engine_client::{EngineClient, EngineClientError};
use crate::server_client::ServerClient;

/// Default heartbeat interval for reconnection attempts.
const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(30);

/// Manages online/offline state for the Policy Engine connection.
///
/// When the engine is unreachable, the manager transitions to offline mode
/// and delegates decisions to the local cache.  A background heartbeat task
/// probes the engine periodically and restores online mode when it responds.
pub struct OfflineManager {
    /// `true` when the Policy Engine is reachable.
    online: Arc<AtomicBool>,
    /// The local decision cache.
    cache: Arc<Cache>,
    /// The HTTPS client to the Policy Engine.
    client: EngineClient,
    /// How often to probe the engine when offline.
    heartbeat_interval: Duration,
    /// Machine hostname, included in heartbeat probe requests.
    machine_name: Option<String>,
    /// Optional client for sending heartbeats to dlp-server.
    /// When set, each heartbeat iteration also pings the central server.
    server_client: Option<ServerClient>,
}

impl OfflineManager {
    /// Constructs a new manager.  Starts in online mode.
    ///
    /// # Arguments
    ///
    /// * `client` -- the HTTPS client to the Policy Engine
    /// * `cache` -- the shared policy decision cache
    /// * `machine_name` -- optional hostname for heartbeat probe requests
    pub fn new(client: EngineClient, cache: Arc<Cache>, machine_name: Option<String>) -> Self {
        Self {
            online: Arc::new(AtomicBool::new(true)),
            cache,
            client,
            heartbeat_interval: HEARTBEAT_INTERVAL,
            machine_name,
            server_client: None,
        }
    }

    /// Constructs a new manager with a custom heartbeat interval.
    #[must_use]
    pub fn with_heartbeat_interval(
        client: EngineClient,
        cache: Arc<Cache>,
        interval: Duration,
        machine_name: Option<String>,
    ) -> Self {
        Self {
            online: Arc::new(AtomicBool::new(true)),
            cache,
            client,
            heartbeat_interval: interval,
            machine_name,
            server_client: None,
        }
    }

    /// Attaches a `ServerClient` for sending heartbeats to dlp-server.
    ///
    /// When set, the heartbeat loop will also call
    /// `server_client.send_heartbeat()` every iteration.
    #[must_use]
    pub fn with_server_client(mut self, sc: ServerClient) -> Self {
        self.server_client = Some(sc);
        self
    }

    /// Returns `true` if the Policy Engine is currently considered reachable.
    #[must_use]
    pub fn is_online(&self) -> bool {
        self.online.load(Ordering::Acquire)
    }

    /// Evaluates a request, falling back to offline mode if the engine
    /// is unreachable.
    ///
    /// 1. If online, sends the request to the engine.
    ///    - On success, caches the result and returns it.
    ///    - On `Unreachable`, transitions to offline and falls through.
    /// 2. If offline, consults the local cache.
    ///    - On cache hit, returns the cached decision.
    ///    - On cache miss, returns [`cache::fail_closed_response`].
    pub async fn evaluate(&self, request: &EvaluateRequest) -> EvaluateResponse {
        if self.is_online() {
            match self.client.evaluate(request).await {
                Ok(response) => {
                    // Cache the successful response.
                    self.cache.insert(
                        &request.resource.path,
                        &request.subject.user_sid,
                        response.clone(),
                    );
                    return response;
                }
                Err(EngineClientError::Unreachable { .. }) => {
                    self.transition_offline();
                }
                Err(e) => {
                    warn!(error = %e, "engine error — falling back to cache");
                }
            }
        }

        // Offline: consult the cache.
        self.offline_decision(request)
    }

    /// Returns a decision from the local cache, or a fail-closed default.
    #[must_use]
    pub fn offline_decision(&self, request: &EvaluateRequest) -> EvaluateResponse {
        if let Some(cached) = self
            .cache
            .get(&request.resource.path, &request.subject.user_sid)
        {
            debug!(
                path = %request.resource.path,
                decision = ?cached.decision,
                "offline: cache hit"
            );
            return cached;
        }

        // Cache miss — apply fail-closed semantics.
        cache::fail_closed_response(request.resource.classification)
    }

    /// Runs the heartbeat loop that probes the engine when offline.
    ///
    /// Intended to run inside `tokio::spawn`.  Exits when the provided
    /// `shutdown` signal resolves.
    pub async fn heartbeat_loop(&self, shutdown: tokio::sync::watch::Receiver<bool>) {
        let mut shutdown = shutdown;
        loop {
            tokio::select! {
                _ = tokio::time::sleep(self.heartbeat_interval) => {}
                _ = shutdown.changed() => {
                    debug!("heartbeat loop shutting down");
                    return;
                }
            }

            // Best-effort heartbeat to dlp-server (independent of
            // Policy Engine online/offline state).
            let server_connected = if let Some(ref sc) = self.server_client {
                let ok = sc.send_heartbeat().await.is_ok();
                if !ok {
                    debug!("dlp-server heartbeat failed (best-effort)");
                }
                ok
            } else {
                false
            };

            // Broadcast the current Agent->Server connection state to all UI clients.
            // The UI stores this atomically and displays it in the tray tooltip.
            // Fire-and-forget — no acknowledgement expected.
            crate::ipc::pipe2::BROADCASTER.broadcast(
                &crate::ipc::messages::Pipe2AgentMsg::ServerConnected {
                    connected: server_connected,
                },
            );

            if self.is_online() {
                continue;
            }

            // Probe the engine with a minimal request.
            debug!("heartbeat: probing Policy Engine");
            let probe = build_probe_request(self.machine_name.as_deref());
            match self.client.evaluate(&probe).await {
                Ok(_) => {
                    self.transition_online();
                }
                Err(_) => {
                    debug!("heartbeat: engine still unreachable");
                }
            }
        }
    }

    /// Transitions to offline mode.
    fn transition_offline(&self) {
        if self.online.swap(false, Ordering::AcqRel) {
            warn!("Policy Engine unreachable — entering offline mode");
        }
    }

    /// Transitions back to online mode.
    fn transition_online(&self) {
        if !self.online.swap(true, Ordering::AcqRel) {
            info!("Policy Engine reachable — resuming online mode");
        }
    }
}

/// Builds a minimal probe request for the heartbeat.
fn build_probe_request(machine_name: Option<&str>) -> EvaluateRequest {
    EvaluateRequest {
        subject: dlp_common::Subject {
            user_sid: "S-1-0-0".to_string(),
            user_name: "heartbeat-probe".to_string(),
            groups: Vec::new(),
            device_trust: dlp_common::DeviceTrust::Unknown,
            network_location: dlp_common::NetworkLocation::Unknown,
        },
        resource: dlp_common::Resource {
            path: "heartbeat-probe".to_string(),
            classification: Classification::T1,
        },
        environment: dlp_common::Environment {
            timestamp: chrono::Utc::now(),
            session_id: 0,
            access_context: dlp_common::AccessContext::Local,
        },
        action: dlp_common::Action::READ,
        agent: machine_name.map(|name| AgentInfo {
            machine_name: Some(name.to_string()),
            current_user: None,
        }),
        ..Default::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use dlp_common::{AccessContext, Action, Decision, Environment, Resource, Subject};

    fn make_request(path: &str, sid: &str, cls: Classification) -> EvaluateRequest {
        EvaluateRequest {
            subject: Subject {
                user_sid: sid.to_string(),
                user_name: "testuser".to_string(),
                groups: Vec::new(),
                device_trust: dlp_common::DeviceTrust::Managed,
                network_location: dlp_common::NetworkLocation::Corporate,
            },
            resource: Resource {
