use std::sync::Arc;
use std::thread::{self, JoinHandle};

use dlp_common::{
    Action, AgentInfo, AuditEvent, Classification, Decision, Environment, EvaluateRequest,
    EvaluateResponse, EventType, NetworkLocation, Resource, Subject,
};
use tracing::{debug, error, info, warn};

use windows::Win32::Foundation::{CloseHandle, HANDLE, WAIT_OBJECT_0};
use windows::Win32::Graphics::Printing::{
    FindFirstPrinterChangeNotification, FindNextPrinterChangeNotification,
    PRINTER_CHANGE_ADD_JOB, PRINTER_CHANGE_SET_JOB, PRINTER_CHANGE_WRITE_JOB,
};
use windows::Win32::System::Threading::WaitForSingleObject;

use crate::audit_emitter::{emit_audit, EmitContext};
use crate::clipboard::ContentClassifier;
use crate::offline::OfflineManager;
use crate::print_job_info::{cancel_job, get_job_info, is_job_printing, open_printer, JobInfo};
use crate::print_xps_parser::extract_text;

